expression:
grel:with(
  value.match(/(?:at|from|seized at|in|to)\s+([A-Z][a-zA-Z\s]+(?:International Airport|Airport|Terminal))/i),
  pairs, 
  if(pairs, 
    pairs[1].trim(), 
    with(
      value.match(/([A-Z][a-zA-Z\s]+(?:International|Airport|Terminal)(?:\s+Airport)?)/),
      altPairs,
      if(altPairs, 
        altPairs[1].trim(), 
        "Airport Not Specified"
      )
    )
  )
)

